"""Visual identity for S-Q-Ali Media Downloader.

Palette: ink-plum base with a cool cyan accent. Status colours are
carried on a vertical spine at the left edge of every queue card, which
is the one signature element of the interface.
"""

C = {
    "bg": "#100E14",
    "panel": "#1A1722",
    "raised": "#241F30",
    "raised_hi": "#2E2840",
    "border": "#332C42",
    "text": "#EFEAF5",
    "muted": "#9C93AE",
    "faint": "#8B83A0",
    "accent": "#22D3EE",
    "accent_hi": "#67E8F9",
    "amber": "#FFB020",
    "done": "#2DD4BF",
    "failed": "#F2547D",
    "queued": "#5A5370",
    "waiting": "#A78BFA",
}

STATUS_COLORS = {
    "Queued": "#5A5370",
    "Downloading": "#22D3EE",
    "Retrying": "#FFB020",
    "Waiting": "#A78BFA",
    "Paused": "#FFB020",
    "Completed": "#2DD4BF",
    "Failed": "#F2547D",
    "Skipped": "#8B83A0",
}

STYLESHEET = '\nQWidget {\n    background: #100E14;\n    color: #EFEAF5;\n    font-family: \'Segoe UI Variable Display\', \'Segoe UI\', \'Inter\', sans-serif;\n    font-size: 13px;\n}\n\n/* ---------- left control rail ---------- */\n#Rail {\n    background: #1A1722;\n    border-right: 1px solid #332C42;\n}\n#Wordmark {\n    font-size: 19px;\n    font-weight: 700;\n    letter-spacing: 3px;\n    color: #EFEAF5;\n    background: transparent;\n}\n#WordmarkSub {\n    font-size: 10px;\n    letter-spacing: 4px;\n    color: #22D3EE;\n    font-weight: 600;\n    background: transparent;\n}\n#RailStripe {\n    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,\n        stop:0 #22D3EE, stop:0.5 #67E8F9, stop:1 #2DD4BF);\n    border: none;\n    border-radius: 2px;\n}\nQLabel[role="section"] {\n    color: #8B83A0;\n    font-size: 10px;\n    font-weight: 700;\n    letter-spacing: 2px;\n    background: transparent;\n}\nQLabel[role="hint"] {\n    color: #8B83A0;\n    font-size: 11px;\n    background: transparent;\n}\nQLabel { background: transparent; }\n\n/* ---------- inputs ---------- */\nQLineEdit, QPlainTextEdit, QComboBox {\n    background: #241F30;\n    border: 1px solid #332C42;\n    border-radius: 8px;\n    padding: 8px 10px;\n    selection-background-color: #22D3EE;\n    selection-color: #14100E;\n}\nQLineEdit:focus, QPlainTextEdit:focus, QComboBox:focus {\n    border: 1px solid #22D3EE;\n}\nQPlainTextEdit {\n    font-family: \'Consolas\', \'Cascadia Mono\', monospace;\n    font-size: 12px;\n}\nQComboBox::drop-down { border: none; width: 26px; }\nQComboBox::down-arrow {\n    image: none;\n    border-left: 4px solid transparent;\n    border-right: 4px solid transparent;\n    border-top: 5px solid #9C93AE;\n    margin-right: 10px;\n}\nQComboBox QAbstractItemView {\n    background: #241F30;\n    border: 1px solid #332C42;\n    selection-background-color: #22D3EE;\n    selection-color: #14100E;\n    outline: none;\n    padding: 4px;\n}\n\n/* ---------- buttons ---------- */\nQPushButton {\n    background: #241F30;\n    border: 1px solid #332C42;\n    border-radius: 8px;\n    padding: 8px 14px;\n    color: #EFEAF5;\n    font-weight: 600;\n}\nQPushButton:hover  { background: #2E2840; border-color: #8B83A0; }\nQPushButton:pressed { background: #1A1722; }\nQPushButton:disabled { color: #8B83A0; border-color: #332C42; background: #1A1722; }\n\nQPushButton[kind="primary"] {\n    background: #22D3EE;\n    border: 1px solid #22D3EE;\n    color: #17100C;\n}\nQPushButton[kind="primary"]:hover { background: #FF8354; border-color: #FF8354; }\nQPushButton[kind="primary"]:disabled { background: #241F30; border-color: #332C42; color: #8B83A0; }\n\nQPushButton[kind="danger"] { color: #F2547D; }\nQPushButton[kind="danger"]:hover { border-color: #F2547D; background: #2E2840; }\n\nQPushButton[kind="ghost"] {\n    background: transparent;\n    border: 1px solid transparent;\n    color: #9C93AE;\n    font-weight: 500;\n    padding: 6px 10px;\n}\nQPushButton[kind="ghost"]:hover { color: #EFEAF5; border-color: #332C42; }\n\n/* ---------- source tabs ---------- */\nQPushButton[kind="tab"] {\n    background: #241F30;\n    border: 1px solid #332C42;\n    border-radius: 8px;\n    padding: 7px 10px;\n    color: #9C93AE;\n    font-size: 12px;\n    font-weight: 600;\n}\nQPushButton[kind="tab"]:hover {\n    color: #EFEAF5;\n    border-color: #8B83A0;\n}\nQPushButton[kind="tab"]:checked {\n    background: #22D3EE;\n    border-color: #22D3EE;\n    color: #17100C;\n}\n\n/* ---------- workspace ---------- */\n#WorkHeader {\n    background: #100E14;\n    border-bottom: 1px solid #332C42;\n}\n#Chip {\n    background: #1A1722;\n    border: 1px solid #332C42;\n    border-radius: 9px;\n}\nQLabel[role="chipValue"] { font-size: 17px; font-weight: 700; background: transparent; }\nQLabel[role="chipLabel"] {\n    font-size: 9px; letter-spacing: 1.5px; color: #8B83A0;\n    font-weight: 700; background: transparent;\n}\n\n#Card {\n    background: #1A1722;\n    border: 1px solid #332C42;\n    border-radius: 10px;\n}\n#Card:hover { border-color: #8B83A0; }\n#Spine { border-radius: 2px; }\nQLabel[role="cardTitle"] { font-size: 13px; font-weight: 600; background: transparent; }\nQLabel[role="cardUrl"] {\n    font-family: \'Consolas\', \'Cascadia Mono\', monospace;\n    font-size: 11px; color: #8B83A0; background: transparent;\n}\nQLabel[role="meta"] {\n    font-family: \'Consolas\', \'Cascadia Mono\', monospace;\n    font-size: 11px; color: #9C93AE; background: transparent;\n}\nQLabel[role="error"] { font-size: 11px; color: #F2547D; background: transparent; }\nQLabel[role="badge"] {\n    background: #241F30;\n    border: 1px solid #332C42;\n    border-radius: 5px;\n    padding: 2px 7px;\n    font-size: 10px;\n    font-weight: 700;\n    letter-spacing: 1px;\n    color: #9C93AE;\n}\nQLabel[role="status"] {\n    font-size: 10px; font-weight: 700; letter-spacing: 1.5px; background: transparent;\n}\n#EmptyState {\n    color: #8B83A0;\n    font-size: 13px;\n    background: transparent;\n}\n\nQProgressBar {\n    background: #241F30;\n    border: none;\n    border-radius: 3px;\n    height: 6px;\n    text-align: center;\n    color: transparent;\n}\nQProgressBar::chunk {\n    border-radius: 3px;\n    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,\n        stop:0 #22D3EE, stop:1 #FFB020);\n}\n\nQCheckBox { spacing: 8px; color: #9C93AE; background: transparent; }\nQCheckBox::indicator {\n    width: 15px; height: 15px;\n    border: 1px solid #332C42;\n    border-radius: 4px;\n    background: #241F30;\n}\nQCheckBox::indicator:hover { border-color: #22D3EE; }\nQCheckBox::indicator:checked {\n    background: #22D3EE;\n    border-color: #22D3EE;\n}\n\nQScrollArea { border: none; background: #100E14; }\n#QueueHost { background: #100E14; }\nQScrollBar:vertical {\n    background: transparent; width: 10px; margin: 2px;\n}\nQScrollBar::handle:vertical {\n    background: #2E2840; border-radius: 5px; min-height: 40px;\n}\nQScrollBar::handle:vertical:hover { background: #8B83A0; }\nQScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; }\nQScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }\n\n#StatusBar {\n    background: #1A1722;\n    border-top: 1px solid #332C42;\n}\nQLabel[role="statusText"] {\n    color: #9C93AE;\n    font-size: 11px;\n    background: transparent;\n}\n\n/* ---------- usage notice ---------- */\n#NoticeBar {\n    background: #241C14;\n    border-top: 1px solid #3E2F1C;\n}\nQLabel[role="notice"] {\n    color: #FFB020;\n    font-size: 11px;\n    font-weight: 600;\n    letter-spacing: 0.2px;\n    background: transparent;\n}\n\n/* ---------- social bar ---------- */\n#SocialBar {\n    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,\n        stop:0 #241F30, stop:1 #1A1722);\n    border-top: 1px solid #22D3EE;\n}\nQLabel[role="follow"] {\n    color: #22D3EE;\n    font-size: 13px;\n    font-weight: 800;\n    letter-spacing: 3px;\n    background: transparent;\n}\n\nQToolTip {\n    background: #241F30;\n    color: #EFEAF5;\n    border: 1px solid #332C42;\n    padding: 5px 8px;\n    border-radius: 6px;\n}\n\n'
